"""Generate double-precision UE vector constants and 2/3-component swizzles."""
from itertools import product
from pathlib import Path

ROOT = Path(__file__).resolve().parents[1]
OUTPUT = ROOT / 'Plugins/DasForUE/Content/Das/Scripts/ue_vector_math.das'

def generate():
    lines = ['options gen2', 'module ue_vector_math public', 'require ue_foundation public', 'require math', '',
             '// Generated by Scripts/GenerateVectorMath.py. Coordinates retain Unreal double precision.']
    constants = {
        'UE_VECTOR_ZERO': (0, 0, 0), 'UE_VECTOR_ONE': (1, 1, 1),
        'UE_VECTOR_FORWARD': (1, 0, 0), 'UE_VECTOR_BACKWARD': (-1, 0, 0),
        'UE_VECTOR_RIGHT': (0, 1, 0), 'UE_VECTOR_LEFT': (0, -1, 0),
        'UE_VECTOR_UP': (0, 0, 1), 'UE_VECTOR_DOWN': (0, 0, -1),
        'UE_VECTOR2D_ZERO': (0, 0), 'UE_VECTOR2D_ONE': (1, 1),
        'UE_VECTOR2D_RIGHT': (1, 0), 'UE_VECTOR2D_LEFT': (-1, 0),
        'UE_VECTOR2D_UP': (0, 1), 'UE_VECTOR2D_DOWN': (0, -1),
    }
    for name, coords in constants.items():
        constructor = 'ue_vector' if len(coords) == 3 else 'ue_vector2d'
        args = ', '.join(f'{value}.0lf' for value in coords)
        lines.append(f'let {name} = {constructor}({args})')
    lines += ['let UE_ROTATOR_ZERO = ue_rotator(0.0lf, 0.0lf, 0.0lf)', '',
              '// Familiar math names delegate to the existing native operations.']
    for vector_type in ('UEVector2D', 'UEVector'):
        for name, native, args in [('dot', 'ue_dot', f'a, b : {vector_type}'),
                                   ('length', 'ue_length', f'value : {vector_type}'),
                                   ('length_sq', 'ue_length_squared', f'value : {vector_type}')]:
            actual = 'a, b' if name == 'dot' else 'value'
            lines += ['', f'def {name}({args}) : double {{', f'    return {native}({actual})', '}']
    for source, axes in [('UEVector2D', 'xy'), ('UEVector', 'xyz')]:
        for size in (2, 3):
            target = 'UEVector2D' if size == 2 else 'UEVector'
            constructor = 'ue_vector2d' if size == 2 else 'ue_vector'
            for parts in product(axes, repeat=size):
                swizzle = ''.join(parts)
                values = ', '.join(f'value.{axis}' for axis in parts)
                lines += ['', f'def operator . {swizzle}(value : {source}) : {target} {{',
                          f'    return {constructor}({values})', '}']
                # Repeated destinations cannot be assigned; snapshot RHS before permuting.
                if len(set(parts)) == size:
                    lines += ['', f'def operator . {swizzle} :=(var value : {source}; replacement : {target}) {{']
                    for index, axis in enumerate('xyz'[:size]):
                        lines.append(f'    let component{index} = replacement.{axis}')
                    for index, axis in enumerate(parts):
                        lines.append(f'    value.{axis} = component{index}')
                    lines.append('}')
    lines += ['', 'def ue_direction_rotation(direction : UEVector) : UERotator {',
              '    let yaw = degrees(atan2(float(direction.y), float(direction.x)))',
              '    let pitch = degrees(atan2(float(direction.z), float(length(direction.xy))))',
              '    return ue_rotator(double(pitch), double(yaw), 0.0lf)', '}']
    return '\n'.join(lines) + '\n'

if __name__ == '__main__':
    OUTPUT.write_text(generate(), encoding='utf-8', newline='\n')
    print(f'Generated {OUTPUT}')
